def handle_request(headers, message, host_context):
    method = message['method']
    if headers.get('Mcp-Method') != method:
        raise ValueError('method header mismatch')
    meta = message['params'].get('_meta', {})
    if not meta.get('io.modelcontextprotocol/protocolVersion'):
        raise ValueError('protocol version required')
    if 'io.modelcontextprotocol/clientCapabilities' not in meta:
        raise ValueError('client capabilities required')
    if method == 'tools/call':
        name = message['params']['name']
        if headers.get('Mcp-Name') != name:
            raise ValueError('tool name header mismatch')
        if name not in host_context['consented_tools']:
            raise PermissionError('consent required')
    return 'validated for dispatch'
